package io.github.mesteriis.rune.keyboard.smarttyping.experiments

import java.nio.ByteBuffer
import java.io.File
import java.util.Base64
import java.util.Properties
import org.junit.Assert.*
import org.junit.Test

/** Golden values are generated by the Python training extractors and pinned dictionary. */
class ContextFeatureParityTest {
    private fun resource(name: String) = javaClass.classLoader!!
        .getResourceAsStream("context-feature-parity/$name")!!.use { it.readBytes() }
    private fun hashes() = Properties().apply { resource("hashes.properties").inputStream().use(::load) }
    private fun text(value: String) = String(Base64.getDecoder().decode(value), Charsets.UTF_8)

    @Test fun kotlinMatchesAllPythonTrainingFeaturesIncludingMissingPairsAndAmbiguity() {
        val hashes = hashes()
        val dictionary = GrammarFeatureDictionary.open(ByteBuffer.wrap(resource("grammar.bin")), hashes.getProperty("grammar"))!!
        val grammar = GrammaticalContextFeatures(dictionary)
        val wiki = WordPairFeatures.open(ByteBuffer.wrap(resource("wiki.bin")), hashes.getProperty("wiki"))!!
        val conversation = WordPairFeatures.open(ByteBuffer.wrap(resource("conversation.bin")), hashes.getProperty("conversation"))!!
        val rows = resource("vectors.tsv").toString(Charsets.UTF_8).lineSequence().filter { it.isNotEmpty() }.toList()
        assertEquals(49, rows.size)
        for ((number, line) in rows.withIndex()) {
            val parts = line.split('\t')
            val context = text(parts[0]); val original = text(parts[1]); val candidate = text(parts[2])
            val actual = listOf(grammar.extract(context, candidate), wiki.extract(context, original, candidate),
                conversation.extract(context, original, candidate))
            for (group in actual.indices) {
                val expected = parts[3 + group].split(',').map(String::toDouble).toDoubleArray()
                assertArrayEquals("case $number group $group", expected, actual[group], 1e-12)
                for (feature in expected.indices) assertEquals("float32 case $number group $group feature $feature",
                    expected[feature].toFloat().toBits(), actual[group][feature].toFloat().toBits())
            }
        }
        // The analyzer's е/ё alternatives and full-analysis ambiguity survive compact projection.
        assertTrue(dictionary.analyses("елки").ambiguity > 0)
        assertTrue(dictionary.analyses("ёлки").ambiguity > 0)
        assertEquals(0, dictionary.analyses("новои\u0306").ambiguity)
        assertEquals(0, dictionary.analyses("фывапролдж").ambiguity)
    }

    @Test fun assetKindsCannotBeSubstituted() {
        val hashes = hashes()
        assertNull(GrammarFeatureDictionary.open(ByteBuffer.wrap(resource("wiki.bin")), hashes.getProperty("wiki")))
        assertNull(WordPairFeatures.open(ByteBuffer.wrap(resource("grammar.bin")), hashes.getProperty("grammar")))
    }

    @Test fun realGrammarPackagedAndStrictReadersMatchPythonFeatureVectors() {
        val bytes = File("src/main/assets/smarttyping/experiments/ru-context.gram").readBytes()
        assertEquals(FrozenContextualAssets.GRAMMAR_BYTES, bytes.size.toLong())
        val strict = GrammarFeatureDictionary.validate(ByteBuffer.wrap(bytes), FrozenContextualAssets.GRAMMAR_SHA256)!!
        val packaged = GrammarFeatureDictionary.openPackaged(ByteBuffer.wrap(bytes).asReadOnlyBuffer(),
            FrozenContextualAssets.GRAMMAR_BYTES)!!
        val strictFeatures = GrammaticalContextFeatures(strict)
        val packagedFeatures = GrammaticalContextFeatures(packaged)
        var count = 0
        for (line in resource("vectors.tsv").toString(Charsets.UTF_8).lineSequence().filter { it.isNotEmpty() }) {
            val parts = line.split('\t')
            val context = text(parts[0]); val candidate = text(parts[2])
            assertEquals(candidate, strict.analyses(candidate), packaged.analyses(candidate))
            val actual = packagedFeatures.extract(context, candidate)
            assertArrayEquals(strictFeatures.extract(context, candidate), actual, 0.0)
            assertArrayEquals(parts[3].split(',').map(String::toDouble).toDoubleArray(), actual, 1e-12)
            count++
        }
        assertEquals(49, count)
    }
}
